import{c as d,Q as a,j as r,m as i}from"./chunks/framework.B2dUnTNU.js";const u=JSON.parse('{"title":"🩺 生存技巧","description":"","frontmatter":{},"headers":[],"relativePath":"survival/index.md","filePath":"survival/index.md","lastUpdated":1779619065000}'),l={name:"survival/index.md"};function e(o,t,n,h,s,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="🩺-生存技巧" tabindex="-1">🩺 生存技巧 <a class="header-anchor" href="#🩺-生存技巧" aria-label="Permalink to &quot;🩺 生存技巧&quot;">​</a></h1><h2 id="⚡-断水断电" tabindex="-1">⚡ 断水断电 <a class="header-anchor" href="#⚡-断水断电" aria-label="Permalink to &quot;⚡ 断水断电&quot;">​</a></h2><p>水电会在游戏开始 <strong>0-30 天内随机切断</strong>。</p><h3 id="应对断水" tabindex="-1">应对断水 <a class="header-anchor" href="#应对断水" aria-label="Permalink to &quot;应对断水&quot;">​</a></h3><ul><li>每家马桶、浴缸、水槽有残余水（~20 单位），尽快用瓶子装起来</li><li><strong>雨水收集桶</strong>：木工 Lv4 可造，下雨自动装满</li><li><strong>河边/湖边</strong>：无限水源，但需要烧开喝</li><li>水桶装满水放在地上也可以当水源</li></ul><h3 id="应对断电" tabindex="-1">应对断电 <a class="header-anchor" href="#应对断电" aria-label="Permalink to &quot;应对断电&quot;">​</a></h3><ul><li><strong>发电机</strong>：仓库/车库/工业区找到，需要电工 Lv3 才能接到家里</li><li>发电机需要<strong>汽油</strong>来运行，加油站可以无限接油</li><li><strong>发电机放室外</strong> — 室内排气会中毒（要命）</li><li>每台发电机可以带 ~20 台冰箱/冰柜</li><li>发电机有耐久度，使用中会慢慢损坏，需要电工修理</li></ul><h2 id="❄️-冬季生存" tabindex="-1">❄️ 冬季生存 <a class="header-anchor" href="#❄️-冬季生存" aria-label="Permalink to &quot;❄️ 冬季生存&quot;">​</a></h2><p>游戏从 7 月开始，冬季大约 <strong>11 月-2 月</strong>。</p><h3 id="寒冷机制" tabindex="-1">寒冷机制 <a class="header-anchor" href="#寒冷机制" aria-label="Permalink to &quot;寒冷机制&quot;">​</a></h3><ul><li>体温过低会降低移动速度和攻击力</li><li>持续低温 → 感冒 → 不治疗 → 肺炎 → 死亡</li></ul><h3 id="保暖方式" tabindex="-1">保暖方式 <a class="header-anchor" href="#保暖方式" aria-label="Permalink to &quot;保暖方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>效果</th></tr></thead><tbody><tr><td>穿多层衣服</td><td>每件衣服有保暖系数 (Insulation)，穿满</td></tr><tr><td>待在室内/车内</td><td>隔绝风雪，基础保温</td></tr><tr><td>营火/壁炉/炉子</td><td>直接加热到暖和</td></tr><tr><td>吃热食/喝热茶</td><td>临时体温提升</td></tr><tr><td>运动</td><td>跑步和战斗临时生成热量</td></tr></tbody></table><h3 id="冬季水" tabindex="-1">冬季水 <a class="header-anchor" href="#冬季水" aria-label="Permalink to &quot;冬季水&quot;">​</a></h3><ul><li>冬天不下雨 → 雨水收集桶不补充</li><li>必须在入冬前储备大量水或搬到河边</li><li>雪不能直接喝（B41 不支持收集雪）</li></ul><h2 id="🏥-医疗" tabindex="-1">🏥 医疗 <a class="header-anchor" href="#🏥-医疗" aria-label="Permalink to &quot;🏥 医疗&quot;">​</a></h2><h3 id="伤口类型与处理" tabindex="-1">伤口类型与处理 <a class="header-anchor" href="#伤口类型与处理" aria-label="Permalink to &quot;伤口类型与处理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>伤情</th><th>处理方式</th><th>恢复时间</th><th>备注</th></tr></thead><tbody><tr><td>刮伤 (Scratch)</td><td>绷带</td><td>1-2 天</td><td>7% 僵尸化</td></tr><tr><td>撕裂伤 (Laceration)</td><td>绷带 → 缝合 (急救 Lv2+)</td><td>2-4 天</td><td>25% 僵尸化</td></tr><tr><td>深伤口 (Deep Wound)</td><td>绷带 → 缝合 (急救 Lv2+)</td><td>3-7 天</td><td>玻璃所致，需取出碎片</td></tr><tr><td>咬伤 (Bite)</td><td>绷带</td><td>不会愈合</td><td>100% 僵尸化，必死</td></tr><tr><td>骨折 (Fracture)</td><td>夹板 (Splint)</td><td>7-14 天</td><td>降低该部位使用能力</td></tr><tr><td>烧伤 (Burn)</td><td>烧伤敷料</td><td>5-10 天</td><td>比普通伤口慢</td></tr><tr><td>感冒/流感</td><td>休息、吃好、保暖</td><td>3-7 天</td><td>严重可导致肺炎</td></tr></tbody></table><h3 id="关键医疗物资" tabindex="-1">关键医疗物资 <a class="header-anchor" href="#关键医疗物资" aria-label="Permalink to &quot;关键医疗物资&quot;">​</a></h3><table tabindex="0"><thead><tr><th>物品</th><th>用途</th><th>重要度</th></tr></thead><tbody><tr><td>绷带 (Bandage)</td><td>止血基本</td><td>⭐⭐⭐⭐⭐</td></tr><tr><td>止痛药 (Painkillers)</td><td>止痛、助眠</td><td>⭐⭐⭐</td></tr><tr><td>抗生素 (Antibiotics)</td><td>抗感染</td><td>⭐⭐⭐</td></tr><tr><td>消毒液 (Disinfectant)</td><td>清洁伤口、防感染</td><td>⭐⭐⭐⭐</td></tr><tr><td>缝合针 (Suture Needle)</td><td>缝合撕裂/深伤口</td><td>⭐⭐⭐⭐</td></tr><tr><td>夹板 (Splint)</td><td>固定骨折</td><td>⭐⭐⭐</td></tr><tr><td>镇定剂 (Beta Blocker)</td><td>消除恐慌、枪战必备</td><td>⭐⭐⭐⭐</td></tr><tr><td>维生素 (Vitamins)</td><td>偶尔消除疲倦</td><td>⭐⭐</td></tr></tbody></table><h2 id="🏗️-安全屋建造" tabindex="-1">🏗️ 安全屋建造 <a class="header-anchor" href="#🏗️-安全屋建造" aria-label="Permalink to &quot;🏗️ 安全屋建造&quot;">​</a></h2><h3 id="基础防御" tabindex="-1">基础防御 <a class="header-anchor" href="#基础防御" aria-label="Permalink to &quot;基础防御&quot;">​</a></h3><ol><li><strong>窗绳逃生</strong> — 二楼每个窗户挂绳子，至少 3 条不同方向</li><li><strong>拆楼梯</strong> — 二楼安全屋终极防御（锤子 + 锯子），僵尸彻底上不来</li><li><strong>封一楼门窗</strong> — 木板 + 钉子右键窗户「Barricade」，每面最多 4 块板</li><li><strong>建围墙</strong> — 木工/金属加工做围栏或墙壁</li></ol><h3 id="进阶设计" tabindex="-1">进阶设计 <a class="header-anchor" href="#进阶设计" aria-label="Permalink to &quot;进阶设计&quot;">​</a></h3><ul><li><strong>双层墙</strong> — 两层木头墙 + 中间空隙，僵尸要拆很久</li><li><strong>气闸室 (Airlock)</strong> — 入口做双门，永远只开一扇</li><li><strong>屋顶花园</strong> — 二楼/屋顶种菜，僵尸上不来</li><li><strong>远程入口</strong> — 绳子进入安全屋，需要靠边站才能爬绳</li></ul><h3 id="长期需求清单" tabindex="-1">长期需求清单 <a class="header-anchor" href="#长期需求清单" aria-label="Permalink to &quot;长期需求清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>物品</th><th>数量</th><th>用途</th></tr></thead><tbody><tr><td>发电机</td><td>2-3 台</td><td>一台供冰箱，一台供电视看录像，一台备用</td></tr><tr><td>汽油桶</td><td>6-10 个</td><td>发电机燃料 + 车辆备用</td></tr><tr><td>雨水收集桶</td><td>4-8 个</td><td>可持续供水</td></tr><tr><td>堆肥桶</td><td>1-2 个</td><td>处理腐烂食材，产肥料</td></tr><tr><td>冰柜</td><td>2-3 个</td><td>长期储存食物</td></tr><tr><td>木箱</td><td>10-20 个</td><td>物资分类收纳</td></tr></tbody></table><h2 id="⏰-life-and-living-电视时间表" tabindex="-1">⏰ Life and Living 电视时间表 <a class="header-anchor" href="#⏰-life-and-living-电视时间表" aria-label="Permalink to &quot;⏰ Life and Living 电视时间表&quot;">​</a></h2><p>每天三个时段播出：</p><table tabindex="0"><thead><tr><th>时间</th><th>节目</th><th>技能</th></tr></thead><tbody><tr><td>06:00</td><td>Woodcraft</td><td>木工</td></tr><tr><td>12:00</td><td>Cooking Show</td><td>烹饪</td></tr><tr><td>18:00</td><td>各种生存节目</td><td>采集、钓鱼、诱捕</td></tr></tbody></table><ul><li>每个节目播出 8-10 天（前 9 天最全）</li><li>没看书的情况下，从 0 级看到最后能到 Lv3-Lv4</li><li>看书 + 看电视 = 飙升</li></ul><h2 id="⚡-快速上线检查清单" tabindex="-1">⚡ 快速上线检查清单 <a class="header-anchor" href="#⚡-快速上线检查清单" aria-label="Permalink to &quot;⚡ 快速上线检查清单&quot;">​</a></h2><p>新档前 7 天最优操作：</p><ol><li><strong>Day 1-2</strong>：找临时安全屋 + 基础武器（撬棍/球棒）</li><li><strong>Day 3-5</strong>：搜刮书店/图书馆 → 技能书</li><li><strong>Day 1-9</strong>：每天 6:00/12:00/18:00 看电视（不可错过）</li><li><strong>Day 5-10</strong>：找发电机 + 接发电机的工具</li><li><strong>Day 7-14</strong>：收集木板和钉子 → 造雨水桶</li><li><strong>Day 14+</strong>：选择永久安全屋 → 开始建家</li><li><strong>断电前</strong>：看完所有 VHS 录像带</li></ol><div class="tip custom-block"><p class="custom-block-title">最重要的生存法则</p><p>不是每个僵尸都需要杀。有时候绕过去比打一场更安全。保持低调，节约武器耐久，存够物资再扩张。</p></div>',35)])])}const g=d(l,[["render",e]]);export{u as __pageData,g as default};
